enum StrideComponent {
    /// X^n C
    XC(Exp),
    /// X^n R
    XR(Exp),
    /// X^a C X^b R
    XCXR { a: Exp, b: Exp },
}

#[derive(Clone, Copy)]
enum StrideCount {
    Right(Exp),
    RightB(Exp),
}

impl StrideComponent {
    /// if can receive this number of strides, return the number of strides sent
    /// otherwise return None
    fn check(&self, n_strides: StrideCount) -> Option<StrideCount> {
        use StrideComponent::*;
        use StrideCount::*;
        match (n_strides, self) {
            (Right(t), XC(n)) => if *n >= t { Some(RightB(t)) } else { None },
            (RightB(t), XC(_)) => Some(Right(2*t)),
            (_, XR(_)) => Some(Right(0)),
            (RightB(_), XCXR { a: _, b: _}) => Some(Right(0)),
            (Right(_), XCXR { a: _, b: _ }) => unimplemented!(),
        }
    }

    /// do strides (updating n) and return step count. this does not check if it can actually 
    /// receive this number of strides.
    fn do_strides(&mut self, n_strides: StrideCount) -> Result<BigInt, SimError> {
        use StrideCount::*;
        match (n_strides, self) {
            (Right(t), Self::XC(n)) => {
                let s = 4 * (*n) - 2*t + 4;
                let out = BigInt::from(s) * BigInt::from(t);
                *n -= t;
                Ok(out)
            }
            (RightB(t), Self::XC(n)) => {
                let s = (8 * (*n)).checked_add(4*t).ok_or_else(|| SimError::Overflow)? + 15;
                let out = BigInt::from(s) * BigInt::from(t);
                *n += t;
                Ok(out)
            }
            (Right(t), Self::XR(n)) => {
                let s0 = (*n).checked_mul(4).ok_or_else(|| SimError::Overflow)?;
                let s1 = t.checked_mul(2).ok_or_else(|| SimError::Overflow)?;
                let out = BigInt::from(s0 + s1 + 1) * BigInt::from(t);
                *n += t;
                Ok(out)
            }
            (RightB(1), sc @ Self::XR(_)) => {
                if let Self::XR(n) = *sc {
                    *sc = Self::XCXR { a: n, b: 1 };
                    Ok(BigInt::from(n) * BigInt::from(8u32) + BigInt::from(13u32))
                } else {
                    unreachable!()
                }
            }
            (RightB(t@ 2..), sc @ Self::XR(_)) => {
                let mut out = sc.do_strides(RightB(1))?;
                out += sc.do_strides(RightB(t-1))?;
                Ok(out)
            }
            (t1 @ RightB(_), Self::XCXR { a, b }) => {
                let mut sc1 = Self::XC(*a);
                let mut sc2 = Self::XR(*b);
                let t2 = sc1.check(t1).unwrap();
                let out = sc1.do_strides(t1)? + sc2.do_strides(t2)?;
                if let Self::XC(a_new) = sc1 {
                    *a = a_new;
                } else {
                    unreachable!();
                }
                if let Self::XR(b_new) = sc2 {
                    *b = b_new;
                } else {
                    unreachable!();
                }
                Ok(out)
            }
            _ => unimplemented!()
        }
    }

    fn write_to_tape(&self, tape: &mut Vec<BlockSymbol>) {
        use BlockSymbol::*;
        use RunSymbolType::*;
        match self {
            Self::XR(n) => {
                tape.push(R);
                if *n > 0 {
                    tape.push(Run(X, *n));
                }
            }
            Self::XC(n) => {
                tape.push(C);
                if *n > 0 {
                    tape.push(Run(X, *n));
                }
            }
            Self::XCXR { a, b } => {
                Self::XR(*b).write_to_tape(tape);
                Self::XC(*a).write_to_tape(tape);
            }
        }
    }
}

impl BlockSimulator {
    pub fn new(do_strides: bool) -> Self {
        use BlockSymbol::*;
        use RunSymbolType::*;
        Self {
            left_tape: vec![L0],
            right_tape: vec![R, Run(X, 2)],
            state: HigherState::RightB,
            base_steps: 24u32.into(),
            self_steps: 0,
            do_strides
        }
    }

    pub fn new_with_tape(
        left_tape: Vec<BlockSymbol>, 
        state: HigherState, 
        right_tape: Vec<BlockSymbol>,
        do_strides: bool,
    ) -> Self {
        Self {
            left_tape, right_tape, state,
            base_steps: BigInt::ZERO,
            self_steps: 0,
            do_strides
        }
    }

    /// Does a stride and returns number of base steps if possible. Returns None if stride not possible.
    fn try_stride(&mut self) -> Result<Option<BigInt>, SimError> {
        let mut n_strides = match self.state {
            HigherState::Left => return Ok(None),
            HigherState::Right => StrideCount::Right(1),
            HigherState::RightB => StrideCount::RightB(1),
        };

        let mut components: Vec<StrideComponent> = Vec::new();
        let mut idx = self.right_tape.len();
        let mut stride_vec = Vec::new();

        let mut done = false;
        while !done {
            use BlockSymbol::*;
            use RunSymbolType::*;

            let comp = match self.right_tape[..idx] {
                [R] => {
                    done = true;
                    StrideComponent::XR(0)
                }
                [R, Run(X, n)] => {
                    done = true;
                    StrideComponent::XR(n)
                }
                [.., C] => {
                    idx -= 1;
                    StrideComponent::XC(0)
                }
                [.., C, Run(X, n)] => {
                    idx -= 2;
                    StrideComponent::XC(n)
                }
                _ => return Ok(None),
            };
            stride_vec.push(n_strides);
            match comp.check(n_strides) {
                Some(n_next) => n_strides = n_next,
                None => return Ok(None),
            }
            components.push(comp);
        }

        let mut n_steps = BigInt::ZERO;
        for (t, comp) in stride_vec.iter().zip(components.iter_mut()) {
            n_steps += comp.do_strides(*t)?;
        }

        self.right_tape.clear();
        for comp in components.iter().rev() {
            comp.write_to_tape(&mut self.right_tape);
        }
        self.state = HigherState::Left;

        Ok(Some(n_steps))
    }

    pub fn step(&mut self) -> Result<(), SimError> {
        if self.do_strides {
            if let Some(new_base_steps) = self.try_stride()? {
                self.base_steps += new_base_steps;
                self.self_steps += 1;
                return Ok(());
            }
        }

        let new_base_steps = self.basic_step()?;
        self.base_steps = self.base_steps.checked_add(new_base_steps.into()).unwrap();
        self.self_steps += 1;
        Ok(())
    }
}

fn compare_stride_sim(n_steps: usize) {
    let mut sim = BlockSimulator::new(false);
    let mut sim_stride = BlockSimulator::new(true);

    for _ in 0..=n_steps {
        while sim.base_steps < sim_stride.base_steps {
            sim.step().unwrap();
        }
        println!("{sim_stride:>width$}", width=(sim.self_steps.checked_ilog10().unwrap_or(0) + 1) as usize);
        println!("{sim}");
        sim_stride.step().unwrap();
    }
}

